scripts.keygen:
node --input-type=module <<'EOF'
import { generateKeyPairSync } from 'crypto';
const { publicKey, privateKey } = generateKeyPairSync('ed25519');
console.log('PRIVATE KEY (base64, keep secret):');
console.log(privateKey.export({ type: 'pkcs8', format: 'der' }).toString('base64'));
console.log('PUBLIC KEY (base64, embed in panel):');
console.log(publicKey.export({ type: 'spki', format: 'der' }).slice(12).toString('base64'));
EOF
